icates harmful, fraudulent, or rule-breaking intent.", "mcPassingThreshold": 0, "hasOpenEndedQuestion": true}, "dmButtonText": "📋 Read Guidelines", "joinSecurity": {"cas": {"apiUrl": "https://api.cas.chat", "enabled": true, "timeout": "00:00:05", "alwaysRun": false, "useGlobal": true, "userAgent": null}, "profileScan": {"enabled": true, "scanOnJoin": true, "banThreshold": 4.0, "notifyThreshold": 2.0, "scanOnProfileChange": true}, "impersonation": {"enabled": true}, "usernameBlacklist": {"enabled": true}}, "denyButtonText": "❌ Decline", "timeoutSeconds": 60, "acceptButtonText": "✅ I Accept", "maxKicksBeforeBan": 4, "mainWelcomeMessage": "👋 Welcome {username} to {chat_name}!\n\nPlease read and accept our community guidelines within {timeout} or you will be temporarily removed.\n\n📖 Our Guidelines:\n1. Dont Be An Asshole\n2. No spam\n\nClick Accept below to continue participating in the chat.", "dmChatTeaserMessage": "Welcome {username}! Click the button below to read the {chat_name} guidelines.\n\nYou have {timeout} to respond."}', '{"overrides": {"Npgsql": 3, "Quartz": 3, "System": 3, "Microsoft": 3, "WTelegram": 2, "Microsoft.Hosting.Lifetime": 2, "Microsoft.EntityFrameworkCore": 3, "Microsoft.EntityFrameworkCore.Database.Command": 3}, "defaultLevel": 2, "lastModified": "2026-03-22T03:08:41.4443505+00:00"}', NULL, NULL, '{"bot_enabled": false}', '{"tier1": {"clamAV": {"host": "clamav", "port": 3310, "enabled": true, "timeoutSeconds": 30}}, "tier2": {"virusTotal": {"enabled": true, "dailyLimit": 500, "perMinuteLimit": 4}, "cloudQueuePriority": ["VirusTotal"], "failOpenWhenExhausted": true}, "general": {"cacheEnabled": true, "cacheTtlHours": 24, "scanFileTypes": [".exe", ".dll", ".zip", ".rar", ".7z", ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".apk", ".dmg", ".pkg", ".bat", ".ps1", ".sh"], "maxFileSizeBytes": 4831838208, "alwaysRunForAllUsers": true}, "lastModified": "2025-11-27T05:58:36.5683881+00:00"}', '{"Jobs": {"DataCleanup": {"Enabled": false, "JobName": "DataCl